# Main function to insert all foods
async def insert_all_foods():
    """Insert all foods into the database"""
    client = AsyncIOMotorClient(MONGO_URL)
    db = client[DB_NAME]
    foods_collection = db.foods
    
    # Combine all food sources
    all_foods = FOODS_DATABASE + FAST_FOOD_DATABASE + WORLD_CUISINES + BRANDED_FOODS
    
    print(f"\n{'='*60}")
    print(f"PhiCor Food Engine - Massive Database Expansion")
    print(f"{'='*60}")
    print(f"Total foods to process: {len(all_foods)}")
    
    inserted = 0
    updated = 0
    skipped = 0
    
    for food in all_foods:
        # Generate ID from name
        food_id = food['name'].lower().replace(' ', '_').replace("'", "").replace('(', '').replace(')', '').replace('/', '_').replace(',', '')
        food_id = ''.join(c for c in food_id if c.isalnum() or c == '_')[:50]
        
        # Calculate organ effects if not present
        if 'organ_effects' not in food:
            food['organ_effects'] = calculate_organ_effects(food.get('nutrients', {}))
        
        # Add metadata
        food_doc = {
            "id": food_id,
            **food,
            "source": food.get('source', 'PhiCor Comprehensive Database'),
            "created_at": datetime.utcnow(),
            "updated_at": datetime.utcnow()
        }
        
        try:
            # Check if exists
            existing = await foods_collection.find_one({"id": food_id})
            if existing:
                # Update existing
                result = await foods_collection.update_one(
                    {"id": food_id},
                    {"$set": food_doc}
                )
                updated += 1
            else:
                # Insert new
                await foods_collection.insert_one(food_doc)
                inserted += 1
                print(f"  ✓ {food['name'][:50]}")
        except Exception as e:
            print(f"  ✗ Error with {food['name']}: {e}")
            skipped += 1
    
    # Get final count
    total_count = await foods_collection.count_documents({})
    
    print(f"\n{'='*60}")
    print(f"Expansion Complete!")
    print(f"{'='*60}")
    print(f"Inserted: {inserted}")
    print(f"Updated: {updated}")
    print(f"Skipped: {skipped}")
    print(f"Total foods in database: {total_count}")
    
    client.close()
    return total_count

if __name__ == "__main__":
    asyncio.run(insert_all_foods())
